CREATE TABLE app_users (
 id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, role ENUM('ADMIN','OPERADOR','CONSULTA') NOT NULL,
 active TINYINT NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY, identity_hash CHAR(64) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(identity_hash,attempted_at)) ENGINE=InnoDB;
CREATE TABLE app_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(50) NOT NULL, entity VARCHAR(60) NOT NULL, record_id VARCHAR(60) NULL, detail TEXT NULL, ip VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_imports (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, module VARCHAR(30) NOT NULL, filename VARCHAR(180) NOT NULL, status VARCHAR(20) NOT NULL, row_count INT NOT NULL, errors TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_import_rows (id BIGINT AUTO_INCREMENT PRIMARY KEY, import_id BIGINT NOT NULL, line_number INT NOT NULL, payload TEXT NOT NULL, errors TEXT NULL, FOREIGN KEY(import_id) REFERENCES app_imports(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_incidents (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT NOT NULL, severity ENUM('BAJA','MEDIA','ALTA','CRITICA') NOT NULL DEFAULT 'MEDIA', status ENUM('ABIERTA','EN_PROCESO','RESUELTA') NOT NULL DEFAULT 'ABIERTA', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
